static inline bool scsi_mode_sense_dbd_is_set(const uint8_t * cdb) {
  return (cdb[1] >> 3) & 1;
}

static inline uint8_t scsi_mode_sense_get_page_code(const uint8_t * cdb) {
  return cdb[2] & 0x3F;
}

static inline uint8_t scsi_mode_sense_get_pc(const uint8_t * cdb) {
  return cdb[2] >> 6;
}

